        "d": "평생 사망을 보장하는 대표 상품이에요. 2025년 상반기 연납화보험료의 54.7%(9,660억 원)를 차지했어요. 요즘은 중장기납 종신보험을 늘려, 2026년 2분기 종신보험의 신계약 보험계약마진 배수가 10.5배까지 올라왔어요."
