      "**상품·계리 직무를 따로 뽑아요.** 2025년 하반기 그룹 공채에서 DB생명은 종합직, 상품계리, 자산운용, 정보기술, 인공지능 다섯 직무를 모집했고, 2026년 하반기 공채에도 '상품/계리' 직무가 있었어요. 2024년 상반기에는 상품개발 경력직도 뽑았어요."
