      "보유 보험계약마진이 다시 늘고 있어요. 2024년 말 2조 4,708억 원까지 줄었다가 2025년 말 2조 8,047억 원, 2026년 6월 말 3조 2,073억 원으로 커졌어요.",
      "새 보장 구조로 배타적사용권을 받아요. 2025년 9월 '치매환자 실종신고 피해보장 특약', 2026년 10월에는 쓰지 않은 치료 보장 한도를 다음 해로 넘겨주는 '한도이연형' 구조로 각각 6개월 배타적사용권을 받았어요.",
      "자본 건전성이 숙제예요. 지급여력비율(킥스)은 경과조치 후 2025년 말 196.03%로 기준을 넘지만, 기본자본만 따진 비율은 2023년 95.84%에서 2025년 38.38%로 떨어졌어요. 금융당국은 2027년부터 이 비율이 50%에 못 미치면 **적기시정조치**를 할 계획이라고 보도됐어요.",
      "자본확충과 외부 성장을 함께 시도했어요. 2026년 3월 1,000억 원 규모 후순위채 발행을 추진했고(희망 금리 연 5.0~5.5%, 매달 이자 지급), 예별손해보험(옛 엠지손해보험) 인수전 본입찰에 참여했지만 2026년 7월 OK금융그룹이 우선협상대상자로 뽑혔어요."
