      "계리·상품개발 지원자라면 공식 직무에 상품계리가 따로 있다는 점을 기억하고, 한도이연형 보장이나 고당지 간편보험처럼 배타적사용권·가격 차등 사례를 들어 위험률과 보험료를 어떻게 설계할지 이야기해보세요."
